wc -l .codex/skills/acef/SKILL.md && sed -n '1,300p' .codex/skills/acef/SKILL.md
wc -l docs/ai/ACEF_CURRENT_CONTEXT.md && sed -n '1,300p' docs/ai/ACEF_CURRENT_CONTEXT.md
wc -l routes/web.php app/Modules/Billing/routes.php app/Modules/Events/routes.php app/Modules/SuperAdmin/Routes/web.php app/Modules/Streaming/routes.php tests/Feature/Authz/LegacyAliasCleanupRegressionTest.php 2>/dev/null || true
git status --short
php -r '
$files = ["routes/web.php", "app/Modules/Billing/routes.php", "app/Modules/Events/routes.php", "app/Modules/SuperAdmin/Routes/web.php", "app/Modules/Streaming/routes.php"];
foreach ($files as $file) {
    $tokens = [];
    foreach (token_get_all(file_get_contents($file)) as $token) {
        if (is_array($token)) {
            if (in_array($token[0], [T_WHITESPACE, T_COMMENT, T_DOC_COMMENT, T_OPEN_TAG], true)) {
                continue;
            }
            $tokens[] = $token[1];
        } else {
            $tokens[] = $token;
        }
    }
    for ($i = count($tokens) - 1; $i >= 0; $i--) {
        if (! in_array($tokens[$i], ["\047route.permission\047", "\042route.permission\042"], true)) {
            continue;
        }
        if ($i >= 3 && $i + 1 < count($tokens) && $tokens[$i - 3] === "->" && $tokens[$i - 2] === "middleware" && $tokens[$i - 1] === "(" && $tokens[$i + 1] === ")") {
            array_splice($tokens, $i - 3, 5);
            $i -= 3;
            continue;
        }
        if ($i + 1 < count($tokens) && $tokens[$i + 1] === ",") {
            array_splice($tokens, $i, 2);
            continue;
        }
        if ($i > 0 && $tokens[$i - 1] === ",") {
            array_splice($tokens, $i - 1, 2);
            $i--;
            continue;
        }
        array_splice($tokens, $i, 1);
    }
    echo $file, " ", hash("sha256", json_encode($tokens, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR)), PHP_EOL;
}
'
wc -l tests/Feature/Authz/LegacyAliasCleanupRegressionTest.php && sed -n '1,300p' tests/Feature/Authz/LegacyAliasCleanupRegressionTest.php
git diff --check -- tests/Feature/Authz/LegacyAliasCleanupRegressionTest.php
